# Market Compass online module: isolated from existing scanners and financial data.
@st.cache_resource(show_spinner=False)
def mc_online_store():
    import sqlite3
    folder=Path('.nse_market_compass');folder.mkdir(exist_ok=True)
    return {'path':str(folder/'cache.sqlite3'),'lock':threading.RLock()}

def mc_cache_read(key):
    import sqlite3
    store=mc_online_store()
    with store['lock'],sqlite3.connect(store['path']) as db:
        db.execute('CREATE TABLE IF NOT EXISTS cache(key TEXT PRIMARY KEY,payload TEXT)')
        row=db.execute('SELECT payload FROM cache WHERE key=?',(key,)).fetchone()
    return json.loads(row[0]) if row else None

def mc_cache_write(key,data):
    import sqlite3
    store=mc_online_store()
    with store['lock'],sqlite3.connect(store['path']) as db:
        db.execute('CREATE TABLE IF NOT EXISTS cache(key TEXT PRIMARY KEY,payload TEXT)')
        db.execute('INSERT OR REPLACE INTO cache VALUES (?,?)',(key,json.dumps(data)))

def mc_needs_update(data):
    if data is None:return True
    try:
        stamp=datetime.fromisoformat(data['updated'])
        return (datetime.now(ZoneInfo('Asia/Kolkata'))-stamp).total_seconds()>600
    except Exception:return True

def mc_date(value):
    if not value:return ''
    value=str(value).strip()
    try:
        if re.match(r'^\d{4}-\d{2}-\d{2}',value):return value[:10]
        return pd.to_datetime(value,dayfirst=True,errors='raise').date().isoformat()
    except Exception:return ''

def mc_event_rows(payload,kind):
    rows=payload if isinstance(payload,list) else payload.get('data',[])
    if not isinstance(rows,list):raise ValueError('NSE event response format changed.')
    output=[]
    for r in rows:
        if kind=='meeting':
            date=mc_date(r.get('bm_date') or r.get('meetingDate') or r.get('date'))
            description=str(r.get('bm_desc') or r.get('purpose') or r.get('desc') or '')
            typ='Scheduled results' if 'result' in description.lower() else 'Board meeting'
        else:
            date=mc_date(r.get('an_dt') or r.get('broadcastDate') or r.get('date'))
            description=str(r.get('desc') or r.get('description') or '')+' '+str(r.get('attchmntText') or '')
            if 'result' not in description.lower():continue
            typ='Results announcement'
        if not date:continue
        output.append({'Date':date,'Symbol':str(r.get('symbol') or ''),'Company':str(r.get('company') or r.get('sm_name') or r.get('symbol') or ''),'Event':typ,'Details':description,'Source':str(r.get('attchmntFile') or r.get('attachment') or 'https://www.nseindia.com/companies-listing/corporate-filings-board-meetings')})
    return output

def mc_fetch_events(start,end):
    session=requests.Session();session.headers.update(HEADERS)
    session.headers.update({'Referer':'https://www.nseindia.com/companies-listing/corporate-filings-board-meetings','Accept':'application/json'})
    session.get('https://www.nseindia.com',timeout=(5,12))
    rows=[];errors=[];ok=0
    for endpoint,kind in [('corporate-board-meetings','meeting'),('corporate-announcements','announcement')]:
        try:
            response=session.get('https://www.nseindia.com/api/'+endpoint,params={'index':'equities','from_date':start.strftime('%d-%m-%Y'),'to_date':end.strftime('%d-%m-%Y')},timeout=(5,20))
            response.raise_for_status();rows.extend(mc_event_rows(response.json(),kind));ok+=1
        except Exception as exc:errors.append(kind+': '+str(exc))
    if not ok:raise ValueError('; '.join(errors))
    rows=[r for r in rows if start.isoformat()<=r['Date']<=end.isoformat()]
    return {'rows':rows,'updated':datetime.now(ZoneInfo('Asia/Kolkata')).isoformat(),'errors':errors,'origin':'NSE online','partial':bool(errors)}

def mc_seed_events(start,end):
    return [{'Date':r['date'],'Symbol':r['symbol'],'Company':r.get('company',r['symbol']),'Event':'Scheduled results' if r.get('type')=='results' else 'Results announcement' if r.get('type')=='published' else 'Board meeting','Details':r.get('description',''),'Source':r.get('url','')} for r in MC_SEED_EVENTS if start.isoformat()<=r['date']<=end.isoformat()]

def mc_show_table(rows,key):
    frame=pd.DataFrame(rows)
    if frame.empty:st.info('No records available for this selection.');return
    if 'Date' in frame:frame['Date']=frame['Date'].map(lambda d:str(d).split('-')[::-1]).map(lambda p:'/'.join(p))
    cfg={'Source':st.column_config.LinkColumn('Source'),'Link':st.column_config.LinkColumn('Source')}
    st.dataframe(frame,use_container_width=True,hide_index=True,column_config=cfg)
    st.download_button('Download displayed records',frame.to_csv(index=False).encode(),'market_compass.csv','text/csv',key=key)

@st.cache_data(ttl=120,show_spinner=False)
def mc_quote(symbol,event_date):
    day=datetime.fromisoformat(event_date).date();today=datetime.now(ZoneInfo('Asia/Kolkata')).date()
    h=yf.Ticker(symbol+'.NS').history(start=day-timedelta(days=10),end=today+timedelta(days=1),auto_adjust=False)
    if h.empty:raise ValueError('No price history returned.')
    dates=[pd.Timestamp(v).date() for v in h.index];close=pd.to_numeric(h['Close'],errors='coerce');prior=[i for i,d in enumerate(dates) if d<day and pd.notna(close.iloc[i])];same=[i for i,d in enumerate(dates) if d==day and pd.notna(close.iloc[i])];valid=[i for i in range(len(dates)) if pd.notna(close.iloc[i])]
    return {'before':float(close.iloc[prior[-1]]) if prior else None,'before_date':dates[prior[-1]] if prior else None,'event':float(close.iloc[same[-1]]) if same else None,'latest':float(close.iloc[valid[-1]]) if valid else None,'latest_date':dates[valid[-1]] if valid else None}

MC_BROKERS=['Jefferies','Motilal Oswal','Morgan Stanley','Goldman Sachs','JPMorgan','Nomura','CLSA','ICICI Securities','HDFC Securities','Axis Securities','JM Financial','Nuvama','Kotak Institutional Equities','Emkay','Elara','UBS','Citi','HSBC','IIFL','BOFA Securities','Bernstein']

def mc_clean_name(value):
    return ' '.join(re.sub(r'[^a-z0-9 ]',' ',str(value).lower()).split())

def mc_match_symbols(text,companies):
    text=' '+mc_clean_name(text)+' ';matched=[]
    for symbol,company in companies.items():
        name=' '.join(re.sub(r'\b(limited|ltd|private|pvt)\b','',mc_clean_name(company)).split())
        phrases=[name]
        clean_symbol=mc_clean_name(symbol)
        if len(clean_symbol)>=3:phrases.append(clean_symbol)
        if any(len(phrase)>=3 and ' '+phrase+' ' in text for phrase in phrases if phrase):matched.append(symbol)
    return sorted(set(matched))


def mc_stock_catalog(event_companies,refresh=False):
    data=mc_cache_read('stock-catalog:v2')
    if data is None or refresh:
        try:
            response=requests.get(NSE_URL,headers=HEADERS,timeout=(4,10));response.raise_for_status()
            frame=pd.read_csv(io.StringIO(response.content.decode('utf-8-sig')));frame.columns=frame.columns.str.strip()
            if not {'SYMBOL','NAME OF COMPANY'}.issubset(frame.columns):raise ValueError('Unexpected stock directory columns')
            names=dict(zip(frame['SYMBOL'].astype(str).str.strip(),frame['NAME OF COMPANY'].astype(str).str.strip()))
            data={'names':names,'updated':datetime.now(ZoneInfo('Asia/Kolkata')).isoformat(),'complete':True};mc_cache_write('stock-catalog:v2',data)
        except Exception as exc:
            # Cache the failure as well; filter clicks must not retry the network.
            data=dict(data or {'names':{},'complete':False});data['error']=str(exc);mc_cache_write('stock-catalog:v2',data)
    companies=dict(data.get('names',{}));companies.update(event_companies)
    if not data.get('complete'):st.caption('Full NSE name directory unavailable; using saved event names. Unmatched articles are listed separately.')
    return companies


def mc_group_broker_calls(calls,companies):
    articles={}
    for row in calls:
        key=(row.get('Date',''),row.get('Broker',''),row.get('Link') or row.get('Headline',''))
        articles.setdefault(key,row)
    grouped={};unmatched=[]
    for row in articles.values():
        symbols=mc_match_symbols(row.get('Headline',''),companies)
        if not symbols:unmatched.append(dict(row,Symbol=''));continue
        for symbol in symbols:
            key=(row.get('Date',''),row.get('Broker',''),symbol)
            group=grouped.setdefault(key,dict(row,Symbol=symbol,Articles=[]))
            group['Articles'].append({'Headline':row.get('Headline',''),'Link':row.get('Link',''),'AmbiguousTarget':len(symbols)>1})
    output=[]
    for group in grouped.values():
        group['Headline']=' | '.join(dict.fromkeys(r['Headline'] for r in group['Articles']))
        output.append(group)
    return output,unmatched


def mc_fetch_broker_month(start,end,companies):
    from concurrent.futures import ThreadPoolExecutor,as_completed
    def fetch(broker):
        term='"'+broker+'" ("target price" OR upgrade OR downgrade OR "buy rating" OR "sell rating" OR overweight OR underweight) India after:'+(start-timedelta(days=1)).isoformat()+' before:'+(end+timedelta(days=2)).isoformat()
        url='https://news.google.com/rss/search?q='+quote_plus(term)+'&hl=en-IN&gl=IN&ceid=IN:en'
        response=requests.get(url,headers=HEADERS,timeout=(5,12));response.raise_for_status();root=ET.fromstring(response.content);rows=[]
        for item in root.findall('.//item'):
            title=html.unescape(item.findtext('title') or '');description=re.sub('<[^>]+>',' ',html.unescape(item.findtext('description') or ''));text=title+' '+description
            if mc_clean_name(broker) not in mc_clean_name(text):continue
            if not re.search(r'target|upgrade|downgrade|\bbuy\b|\bsell\b|overweight|underweight|rating',text,re.I):continue
            day=mc_date(item.findtext('pubDate'))
            if not day or not (start-timedelta(days=1)).isoformat()<=day<=(end+timedelta(days=1)).isoformat():continue
            source=item.find('source');source=source.text if source is not None else ''
            symbols=mc_match_symbols(text,companies)
            # Unmatched reports remain visible; never guess a stock assignment.
            for symbol in symbols or ['']:
                rows.append({'Date':day,'Broker':broker,'Symbol':symbol,'Headline':title,'Publisher':source,'Link':item.findtext('link') or ''})
        return rows
    output=[];errors=[]
    with ThreadPoolExecutor(max_workers=6) as pool:
        futures={pool.submit(fetch,b):b for b in MC_BROKERS}
        for future in as_completed(futures):
            try:output.extend(future.result())
            except Exception as exc:errors.append(futures[future]+': '+str(exc))
    if len(errors)==len(MC_BROKERS):raise ValueError('All brokerage news requests failed.')
    unique={(r['Date'],r['Broker'],r['Symbol'],r['Link'] or r['Headline']):r for r in output}
    return {'rows':list(unique.values()),'errors':errors,'updated':datetime.now(ZoneInfo('Asia/Kolkata')).isoformat()}

def mc_broker_names(event,calls):
    day=datetime.fromisoformat(event['Date']).date()
    return sorted({r['Broker'] for r in calls if r['Symbol']==event['Symbol'] and abs((datetime.fromisoformat(r['Date']).date()-day).days)<=1})

@st.cache_data(ttl=180,show_spinner=False)
def mc_batch_prices(events_tuple):
    events=[{'Symbol':s,'Date':d} for s,d in events_tuple];symbols=sorted({e['Symbol'] for e in events if e['Symbol']});today=datetime.now(ZoneInfo('Asia/Kolkata')).date();first=min([datetime.fromisoformat(e['Date']).date() for e in events]+[today])-timedelta(days=12)
    histories={};errors=[]
    for offset in range(0,len(symbols),60):
        group=symbols[offset:offset+60];tickers=[s+'.NS' for s in group]
        try:
            frame=yf.download(tickers,start=first,end=today+timedelta(days=1),auto_adjust=False,group_by='ticker',threads=True,progress=False,timeout=15)
            for symbol,ticker in zip(group,tickers):
                try:
                    if isinstance(frame.columns,pd.MultiIndex):
                        if ticker in frame.columns.get_level_values(0):part=frame[ticker]
                        else:part=frame.xs(ticker,axis=1,level=1)
                    else:part=frame
                    close=pd.to_numeric(part['Close'],errors='coerce').dropna()
                    if not close.empty:histories[symbol]=[(pd.Timestamp(i).date(),float(v)) for i,v in close.items()]
                except Exception:errors.append(symbol)
        except Exception:errors.extend(group)
    output={}
    for event in events:
        points=histories.get(event['Symbol'],[]);day=datetime.fromisoformat(event['Date']).date();prior=[v for v in points if v[0]<day];same=[v for v in points if v[0]==day]
        if not points:continue
        before=prior[-1][1] if prior else None;latest=points[-1][1]
        output[event['Symbol']+'|'+event['Date']]={'before':before,'event':same[-1][1] if same else None,'latest':latest,'latest_date':points[-1][0].isoformat(),'change':(latest/before-1)*100 if before and day<=today else None}
    return {'prices':output,'errors':sorted(set(errors)),'updated':datetime.now(ZoneInfo('Asia/Kolkata')).isoformat()}

def mc_call_tone(headline,latest=None):
    """Headline-only signal, separate from the stock's realised price change."""
    text=str(headline or '').lower()
    positive=bool(re.search(r'\b(?:rais\w*|hik\w*|lift\w*|increas\w*)\b.{0,45}\b(?:target|pt)\b|\b(?:target|pt)\b.{0,30}\b(?:rais\w*|hik\w*|lift\w*|increas\w*)\b',text))
    negative=bool(re.search(r'\b(?:cut\w*|slash\w*|lower\w*|reduc\w*)\b.{0,45}\b(?:target|pt)\b|\b(?:target|pt)\b.{0,30}\b(?:cut\w*|slash\w*|lower\w*|reduc\w*)\b',text))
    if positive or negative:
        return ('neutral','Mixed target changes') if positive and negative else ('positive','Target raised') if positive else ('negative','Target lowered')
    positive=bool(re.search(r'\b(?:buy|outperform|overweight|bullish|upgrade\w*)\b',text))
    negative=bool(re.search(r'\b(?:sell|underperform|underweight|bearish|downgrade\w*)\b',text))
    if positive or negative:
        return ('neutral','Mixed / unclear call') if positive and negative else ('positive','Positive call') if positive else ('negative','Negative call')
    # A target alone is not a rating or a target revision. Leave it neutral.
    return 'neutral','No clear direction in headline'


def mc_broker_badges(event,calls):
    day=datetime.fromisoformat(event['Date']).date();matched={}
    for row in calls:
        if row.get('Symbol')==event['Symbol'] and abs((datetime.fromisoformat(row['Date']).date()-day).days)<=1:
            matched.setdefault(row['Broker'],[]).append(row)
    badges=[]
    for broker,rows in sorted(matched.items()):
        latest=max(r['Date'] for r in rows);rows=[r for r in rows if r['Date']==latest]
        signals=[mc_call_tone(r.get('Headline','')) for r in rows];tones={tone for tone,reason in signals if tone!='neutral'}
        tone=next(iter(tones)) if len(tones)==1 else 'neutral'
        colour={'positive':'#31d47b','negative':'#ff7777','neutral':'#d6c3ff'}[tone]
        tip=' | '.join(reason+': '+str(row.get('Headline','')) for row,(_,reason) in zip(rows,signals))
        if len(tones)>1:tip='Mixed calls — '+tip
        badges.append('<span style="color:'+colour+';font-weight:700" title="'+html.escape(tip,quote=True)+'">'+html.escape(broker)+'</span>')
    return ' · '.join(badges) or '<span style="color:#afc1cf">No matching sourced call</span>'


def mc_card_html(event,quote,brokers,deals):
    q=quote or {};change=q.get('change');colour='#31d47b' if change is not None and change>0 else '#ff7777' if change is not None and change<0 else '#edf4f8'
    def esc(value):return html.escape(str(value))
    def price(value):return '₹'+dashboard_indian_price(value) if value is not None else 'Unavailable'
    def link(url):return url if str(url).startswith(('https://','http://')) else ''
    names=mc_broker_badges(event,brokers)
    pct=(' ('+f'{change:+.2f}'+'%)') if change is not None else ''
    deal_types=sorted({r.get('Deal Type','') for r in deals if r.get('Symbol')==event['Symbol'] and r.get('Date')==event['Date']})
    return '<article class="mc-card"><div class="mc-meta">'+esc(event['Date'].split('-')[::-1][0]+'/'+event['Date'][5:7]+'/'+event['Date'][:4]+' · '+event['Event'])+'</div><div class="mc-heading"><h3 style="color:'+colour+'">'+esc(event['Company']+' ('+event['Symbol']+')')+'</h3><span class="mc-brokers">'+names+'</span></div><p>'+esc(event.get('Details',''))+'</p><div class="mc-prices"><div><small>Before-event close</small><b>'+esc(price(q.get('before')))+'</b></div><div><small>Event-day close</small><b>'+esc(price(q.get('event')))+'</b></div><div><small>Latest available close</small><b style="color:'+colour+'">'+esc(price(q.get('latest'))+pct)+'</b></div></div><div class="mc-meta">'+esc(('Price date '+q.get('latest_date','').split('-')[::-1][0]+'/'+q.get('latest_date','')[5:7]+'/'+q.get('latest_date','')[:4]+' · Yahoo Finance closing prices') if q.get('latest_date') else 'Price unavailable; no guessed percentage')+((' · '+esc('/'.join(deal_types))+' deal on event date') if deal_types else '')+' · <a href="'+esc(link(event.get('Source','')))+'" target="_blank" rel="noopener">Event source ↗</a></div></article>'

def mc_daily_call_rows(calls,selected,companies,prices):
    daily=[r for r in calls if r.get('Date')==selected]
    attribution={}
    for r in daily:
        attribution.setdefault((r.get('Link') or r.get('Headline','')),set()).add(r.get('Symbol',''))
    output=[]
    for number,r in enumerate(sorted(daily,key=lambda r:(r.get('Broker',''),r.get('Symbol',''),r.get('Headline',''))),1):
        symbol=r.get('Symbol','');q=prices.get(symbol+'|'+selected,{})
        articles=r.get('Articles')
        if articles is not None:
            targets={target_from_text(a.get('Headline','')) for a in articles if not a.get('AmbiguousTarget')}
            targets.discard(None);target=next(iter(targets)) if len(targets)==1 else None
        else:target=target_from_text(r.get('Headline','')) if symbol and len(attribution.get(r.get('Link') or r.get('Headline',''),set()))==1 else None
        tone,reason=mc_call_tone(r.get('Headline',''))
        output.append({'Sl No':number,'Brokerage':r.get('Broker',''),'Stock':companies.get(symbol,symbol) if symbol else 'Stock not identified','Symbol':symbol or '—','Target Price ₹':target,'Latest Close ₹':q.get('latest'),'Price Date':datetime.fromisoformat(q['latest_date']).strftime('%d/%m/%Y') if q.get('latest_date') else 'Unavailable','Call':reason,'Headline':r.get('Headline',''),'Source':r.get('Link','')})
    return output


def mc_render_daily_calls(calls,selected,companies,prices):
    rows=mc_daily_call_rows(calls,selected,companies,prices)
    st.markdown('### Brokerage calls · '+datetime.fromisoformat(selected).strftime('%d/%m/%Y')+' · '+str(len(rows)))
    st.caption('One row per brokerage + stock + date; repeated articles are combined. Counts match the calendar. Targets require an explicit single-stock headline; conflicting targets are left unavailable. Latest closes are not live quotes.')
    if not rows:st.info('No sourced calls loaded for this date.');return
    frame=pd.DataFrame(rows)
    def colour(row):
        tone,_=mc_call_tone(row['Headline']);c={'positive':'#31d47b','negative':'#ff7777','neutral':'#d6c3ff'}[tone]
        return ['color: '+c if name in ['Brokerage','Call'] else '' for name in row.index]
    styled=frame.style.apply(colour,axis=1).format({'Target Price ₹':lambda v:'₹'+dashboard_indian_price(v),'Latest Close ₹':lambda v:'₹'+dashboard_indian_price(v)},na_rep='Unavailable')
    st.dataframe(styled,hide_index=True,use_container_width=True,column_config={'Source':st.column_config.LinkColumn('Source',display_text='Read ↗')})
    st.download_button('Download selected-day calls',frame.to_csv(index=False).encode('utf-8-sig'),'brokerage_calls_'+selected+'.csv','text/csv',key='mc_daily_calls_csv')


def mc_deal_refresh(data,start,end,refresh=False):
    """Keep saved rows on errors and cache failed attempts to avoid repeated retries."""
    from datetime import date as Date
    today=datetime.now(ZoneInfo('Asia/Kolkata')).date()
    if start>today:return data
    if not refresh and data and not mc_needs_update({'updated':data.get('attempted',data.get('updated',''))}):return data
    result=dict(data or {});rows=list(result.get('rows',[]));errors=[];success=[]
    for kind in ['Bulk','Block']:
        try:
            fresh=deals_fetch(start,min(end,today),kind)
            rows.extend(fresh);success.append(kind)
        except Exception as exc:errors.append(kind+': '+str(exc))
    keys=['Date','Symbol','Client','Action','Quantity','Avg Price','Deal Type']
    result['rows']=list({tuple(str(r.get(k,'')) for k in keys):r for r in rows}.values())
    now=datetime.now(ZoneInfo('Asia/Kolkata')).isoformat()
    result.update(attempted=now,errors=errors)
    if success:result['updated']=now;result['origin']='NSE online reports + saved/imported records'
    mc_cache_write('deals:'+start.strftime('%Y-%m'),result)
    return result


def mc_import_deal_reports():
    with st.expander('Import NSE bulk / block CSV reports if online update is blocked'):
        st.caption('Download a CSV from the official NSE report page, choose its deal type and upload. Existing records are kept; duplicate rows are merged. Imports are saved in the app cache, not a permanent external backup.')
        st.link_button('Open official NSE deal reports','https://www.nseindia.com/report-detail/display-bulk-and-block-deals',key='mc_import_source')
        kind=st.selectbox('Report type',['Bulk','Block'],key='mc_import_kind')
        uploads=st.file_uploader('NSE CSV reports',type=['csv'],accept_multiple_files=True,key='mc_deal_upload')
        if st.button('Save uploaded reports',key='mc_import_save',disabled=not uploads):
            imported=[];failures=[]
            for upload in uploads or []:
                try:
                    raw=upload.getvalue()
                    try:text=raw.decode('utf-8-sig')
                    except UnicodeDecodeError:text=raw.decode('cp1252')
                    rows=deals_normalize(pd.read_csv(io.StringIO(text)),kind)
                    if not rows:raise ValueError('No valid deal rows found. Check the dates and numeric columns.')
                    imported.extend(rows)
                except Exception as exc:failures.append(upload.name+': '+str(exc))
            for error in failures:st.error(error)
            months=sorted({r['Date'][:7] for r in imported})
            for month in months:
                key='deals:'+month;old=mc_cache_read(key) or {};rows=list(old.get('rows',[]))+[r for r in imported if r['Date'].startswith(month)]
                fields=['Date','Symbol','Client','Action','Quantity','Avg Price','Deal Type']
                old['rows']=list({tuple(str(r.get(k,'')) for k in fields):r for r in rows}.values())
                old['imported_at']=datetime.now(ZoneInfo('Asia/Kolkata')).isoformat();old['origin']='Uploaded NSE CSV + saved records'
                mc_cache_write(key,old)
            if imported:st.success(str(len(imported))+' report rows processed for '+', '.join(months)+'. Select that month to view them.')


